test('vatSummary - empty invoices array', () => {
  const result = vatSummary([]);
  assert.equal(result.length, 0);
});

test('vatSummary - excludes draft invoices', () => {
  const invoices = [
    {
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 19 }],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 0);
});

test('vatSummary - single rate', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 19 }],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 19);
  assert.equal(result[0].base, 100);
  assert.equal(result[0].vat, 19);
});

test('vatSummary - multiple lines same rate', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 19 },
        { qty: 2, unitPrice: 50, discountPercent: 0, vatRate: 19 },
      ],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 19);
  assert.equal(result[0].base, 200);
  assert.equal(result[0].vat, 38);
});

test('vatSummary - multiple rates sorted high to low', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 5 },
        { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 19 },
        { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 7 },
      ],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 3);
  assert.equal(result[0].rate, 19);
  assert.equal(result[1].rate, 7);
  assert.equal(result[2].rate, 5);
});

test('vatSummary - applies discounts to base', () => {
