test('lateFee - not overdue returns 0', () => {
  const invoice = {
    dueDate: '2026-10-20',
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };

  const fee = lateFee(invoice, '2026-10-15');
  assert.equal(fee, 0);
});

