  };

  const fee = lateFee(invoice, '2026-04-11');
  // 100 days overdue (Jan 1 to Apr 11)
  // 10000 * 0.0004 * 100 = 400
  assert.equal(fee, 400);
});

test('lateFee - zero amount due', () => {
