    },
    {
      status: 'issued',
      customerId: 'C2',
      dueDate: '2026-10-20',
      lines: [{ qty: 1, unitPrice: 200, discountPercent: 0, vatRate: 0 }],
    },
    {
      status: 'partially_paid',
      customerId: 'C3',
      dueDate: '2026-10-20',
      lines: [{ qty: 1, unitPrice: 300, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 100, date: '2026-10-10' }],
    },
    {
      status: 'paid',
      customerId: 'C4',
      dueDate: '2026-10-20',
