test('dashboard - identifies top customers by amount due', () => {
  const invoices = [
    {
      status: 'issued',
      customerId: 'C1',
      dueDate: '2026-10-20',
      lines: [{ qty: 1, unitPrice: 500, discountPercent: 0, vatRate: 0 }],
    },
    {
      status: 'issued',
      customerId: 'C2',
      dueDate: '2026-10-20',
      lines: [{ qty: 1, unitPrice: 300, discountPercent: 0, vatRate: 0 }],
    },
    {
      status: 'issued',
      customerId: 'C3',
      dueDate: '2026-10-20',
      lines: [{ qty: 1, unitPrice: 200, discountPercent: 0, vatRate: 0 }],
    },
    {
      status: 'issued',
      customerId: 'C4',
      dueDate: '2026-10-20',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
  ];

  const result = dashboard(invoices, '2026-10-15');
  assert.equal(result.topCustomers.length, 3);
  assert.equal(result.topCustomers[0].customerId, 'C1');
  assert.equal(result.topCustomers[0].due, 500);
  assert.equal(result.topCustomers[1].customerId, 'C2');
  assert.equal(result.topCustomers[1].due, 300);
  assert.equal(result.topCustomers[2].customerId, 'C3');
  assert.equal(result.topCustomers[2].due, 200);
});

