test('dashboard - complex scenario with mixed statuses and multiple customers', () => {
  const invoices = [
    {
      status: 'draft',
      customerId: 'C1',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
    {
      status: 'issued',
      customerId: 'C1',
      dueDate: '2026-10-10',
      lines: [{ qty: 1, unitPrice: 200, discountPercent: 0, vatRate: 0 }],
    },
    {
      status: 'issued',
      customerId: 'C2',
      dueDate: '2026-10-20',
      lines: [{ qty: 1, unitPrice: 500, discountPercent: 0, vatRate: 0 }],
    },
    {
      status: 'partially_paid',
      customerId: 'C2',
      dueDate: '2026-10-20',
      lines: [{ qty: 1, unitPrice: 300, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 100, date: '2026-10-10' }],
    },
    {
      status: 'partially_paid',
      customerId: 'C3',
      dueDate: '2026-10-10',
      lines: [{ qty: 1, unitPrice: 150, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 50, date: '2026-10-10' }],
    },
    {
      status: 'paid',
      customerId: 'C3',
      dueDate: '2026-10-20',
      lines: [{ qty: 1, unitPrice: 80, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 80, date: '2026-10-10' }],
    },
  ];

  const result = dashboard(invoices, '2026-10-15');

  assert.deepEqual(result.counts, { draft: 1, issued: 2, partially_paid: 2, paid: 1 });
  // Outstanding: C1:200 + C2:500+200 + C3:100 = 1000
  assert.equal(result.outstanding, 1000);
  // Overdue: C1:200 + C3:100 = 100 (2 invoices due before 2026-10-15)
  assert.equal(result.overdue.count, 2);
  assert.equal(result.overdue.amount, 300);
  // Top customers: C2:700, C1:200, C3:100
  assert.equal(result.topCustomers.length, 3);
  assert.equal(result.topCustomers[0].customerId, 'C2');
  assert.equal(result.topCustomers[0].due, 700);
  assert.equal(result.topCustomers[1].customerId, 'C1');
  assert.equal(result.topCustomers[1].due, 200);
  assert.equal(result.topCustomers[2].customerId, 'C3');
  assert.equal(result.topCustomers[2].due, 100);
});

